CREATE TABLE IF NOT EXISTS logs(id BIGINT AUTO_INCREMENT PRIMARY KEY, ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP, level VARCHAR(10), msg VARCHAR(600));
CREATE TABLE IF NOT EXISTS runs(id BIGINT AUTO_INCREMENT PRIMARY KEY, ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP, step VARCHAR(30), status VARCHAR(10), seconds DOUBLE, detail VARCHAR(400));
CREATE TABLE IF NOT EXISTS baseline(id BIGINT AUTO_INCREMENT PRIMARY KEY, ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP, records INT, fingerprint VARCHAR(80));
CREATE TABLE IF NOT EXISTS recoveries(id BIGINT AUTO_INCREMENT PRIMARY KEY, ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP, restore_name VARCHAR(80), result VARCHAR(10), checks VARCHAR(20), restore_s DOUBLE, verify_s DOUBLE, total_s DOUBLE);
